import os
import errno
import datetime
import logging
import time
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable  # type: ignore
from functools import wraps
from taf.ul.sc.perf.util.helpers import get_default_args
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


def run_method_depend_on_type(wrapped_method):
    """
    Sample usage:
        @run_method_depend_on_type
        def perform_full_commissioning(self, commissioning_file, wait_for_on_air=True, method_type='EMS'):
            pass
    :param wrapped_method:
    :return:
    """
    @wraps(wrapped_method)
    def wrapper(self, *args, **kwargs):
        wrapped_method_name = wrapped_method.__name__
        oam_object = None
        method_type = kwargs.pop('method_type', None)
        if not method_type:
            method_type = get_default_args(wrapped_method)['method_type']

        if method_type == 'REST_API':
            oam_object = self.rest
        elif method_type == 'EMS':
            oam_object = self.ems

        method = getattr(oam_object, mapped_functions[wrapped_method_name][method_type])
        result = method(*args, **kwargs)

        return result

    return wrapper


mapped_functions = {
    'perform_full_commissioning': {
        'REST_API': 'perform_commissioning',
        'EMS': 'perform_full_commissioning'
    }
}


class AirScaleFunctionality(object):

    @property
    def name(self):
        return self.bts.fct.name

    @log_debug_function_info()
    def get_version(self, attemps=5):
        attempt = 1
        while attempt <= attemps:
            logging.debug("Getting eNB version. Attempt: {}".format(attempt))
            try:
                sw_version = self.api.get_sw_version()
                if sw_version:
                    return sw_version
            except DataNotAvailable:
                attempt = attempt + 1
                time.sleep(5)
        logging.warn("Getting eNB version failed. Setting to UNRECOGNIZED")
        return 'UNRECOGNIZED'

    @log_debug_function_info()
    def get_release(self):
        return self.api.get_release_version()

    def get_uptime(self, from_file=False):
        return self.bts.fct.get_uptime(from_file=from_file)

    @log_function_status_to_console(msg="Collect snapshot", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_snapshot(self, log_dir):
        """
        Collect snapshot from the AirScale.

        :param log_dir: full path to snapshot
        :return: None
        """

        try:
            os.makedirs(log_dir)
        except OSError as e:
            if e.errno != errno.EEXIST:
                raise

        now = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        file_name = "{}_Snapshot_{}.zip".format(self.name, now)
        snapshot_path = os.path.join(log_dir, file_name)

        self.api.collect_snapshot(snapshot_path=snapshot_path)

    @log_function_status_to_console(msg="Collect configuration", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_configuration(self, log_dir):
        try:
            os.makedirs(log_dir)
        except OSError as e:
            if e.errno != errno.EEXIST:
                raise

        now = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        file_name = "{}_SCF_{}.xml".format(self.name, now)
        self.api.get_current_scf_file(local_dir_path=log_dir, file_name=file_name)
        self._collect_swconfig(log_dir)

    @log_function_status_to_console(msg="Collect additional logs", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_additional_logs(self, log_dir):
        # TODO: get get_raw_alarm_history and journal via API
        pass

    @log_function_status_to_console(msg="Perform full commissioning", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def perform_full_commissioning(self, commissioning_file, wait_for_on_air=False, method_type='REST_API'):
        result = None
        if method_type == 'REST_API':
            result = self.api.perform_commissioning(scf_file=commissioning_file, skip_parameter_relation_errors=True)
        elif method_type == 'EMS':
            result = self.ems.cli.perform_full_commissioning(commissioning_file, wait_for_on_air)

        return result

    @log_function_status_to_console(msg="Change configuration", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def perform_recommissioning(self, params, method_type='REST_API'):
        result = None
        if method_type == 'REST_API':
            # delta = self._prepare_delta(params) # could be helpful in the feature. Eg automatically getting MRBTS-id
            result = self.api.perform_recommissioning(delta=params)
        elif method_type == 'EMS':
            result = self.ems.cli.perform_recommissioning(params=params)

        return result

    @log_debug_function_info()
    def wait_for_onair(self, timeout=900, method_type='REST_API', raise_error=True):
        status = None
        if method_type == 'REST_API':
            status = self.api.wait_for_onair(timeout=timeout, allow_degraded_status=True, raise_error=raise_error)
        elif method_type == 'EMS':
            status = self.wait_for_onair_via_ems()

        return status

    @log_function_status_to_console(msg="Start Benchmark stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_benchmark_stats_collecting(self, period=None):
        self._start_benchmark_stats_collecting(device=self.bts.fct, period=period)

    @log_function_status_to_console(msg="Stop Benchmark stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_benchmark_stats_collecting(self):
        self._stop_benchmark_stats_collecting(device=self.bts.fct)

    @log_function_status_to_console(msg="Start DSP stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_dsp_stats_collecting(self):
        self._start_dsp_stats_collecting(workstation=self.ws, dsp_script=self.dsp_script)

    @log_function_status_to_console(msg="Stop DSP stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_dsp_stats_collecting(self):
        self._stop_dsp_stats_collecting(workstation=self.ws, dsp_script=self.dsp_script)

    @log_function_status_to_console(msg="Software update", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def software_update(self, sw_package, timeout=1800):
        """
        AirScale software update.

        :param sw_package: full path to build file
        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: software update status
        """

        try:
            os.path.exists(sw_package)
        except OSError as e:
            if e.errno != errno.EEXIST:
                raise

        return self.api.software_update(sw_package=sw_package, timeout=timeout)

    def get_active_alarms(self, timeout=30):
        """"
        Get a list of active alarms from the AirScale.

        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: alarm list
        """

        return self.api.get_active_alarms(timeout=timeout)

    def get_active_alarms_number(self, timeout=30):
        """"
        Get a number of active alarms from the AirScale.

        :param timeout: time in seconds, after timeout expires an exception is raised
        :return: number of active alarms
        """

        return self.api.get_active_alarms_number(timeout=timeout)
